    static boolean allowsLegacyCatalogEditing(ReSyncFlowClient.CatalogAuthority authority) {
        return ReSyncFlowClient.catalogAuthorityAllowsLegacyEditing(authority);
    }

    static boolean allowsTypedMutation(ReSyncFlowClient.CatalogAuthority authority) {
        return ReSyncFlowClient.catalogAuthorityAllowsTypedMutation(authority);
    }

    private Optional<ReSyncGenericDescriptorProjection.Projection> typedDescriptorProjection(
        ReSyncFlowClient client, String owner, String nodeId) {
        ContractRef<NodeId> identity = FlowNodeWidget.typedNodeIdentity(owner, nodeId);
        return identity == null || client != typedCatalogClient() ? Optional.empty() : typedInteractionProjection()
            .flatMap(projection -> projection.descriptor(identity));
    }

    private Optional<ReSyncGenericWidgetCapabilities.WidgetDefinition> typedWidgetDefinition(
        ReSyncFlowClient client, String owner, String nodeId) {
        ContractRef<NodeId> identity = FlowNodeWidget.typedNodeIdentity(owner, nodeId);
        return identity == null || client != typedCatalogClient() ? Optional.empty() : typedInteractionProjection()
            .flatMap(projection -> projection.widgetDefinition(identity));
    }

    private boolean typedDescriptorRenderable(ReSyncGenericDescriptorProjection.Projection projection) {
        return projection != null && switch (projection.status()) {
            case ACTIVE, READ_ONLY -> true;
            case UNAVAILABLE, OPAQUE, INVALID, TOMBSTONED -> false;
        };
    }

    private boolean typedDescriptorEditable(ReSyncGenericDescriptorProjection.Projection projection) {
        return projection != null && projection.status() == ReSyncGenericDescriptorProjection.Status.ACTIVE
            && !projection.readOnly();
    }

    private boolean hasAuthoritativeNodeCatalog() {
        if (!legacyCatalogAllowed()) {
            return false;
        }
        NodeRegistry registry = NodeRegistry.getInstance();
        return registry != null && registry.hasCanonicalCatalogAuthority(nodeRegistryServerId());
    }

    private boolean isEditableNode(String nodeId) {
        if (nodeId == null || graph == null) {
            return false;
        }
        if (isActiveCoreStudioDocument()) {
            CoreGraphEditorSession session = coreInteractionSession();
            return session != null && coreAuthoringNegotiated()
                && coreNode(session, nodeId) != null
                && widgetCache.get(nodeId) != null && widgetCache.get(nodeId).isEditable()
                && coreCapabilityAllowed(nodeId);
        }
        if (!catalogAuthorityAllowsInteraction()) {
            return false;
        }
        if (!hasTypedCatalogProjection() && !hasAuthoritativeNodeCatalog()) {
            return false;
        }
        FlowNode node = graph.getNodes().get(nodeId);
        FlowNodeWidget widget = widgetCache.get(nodeId);
        return node != null && widget != null && widget.isEditable()
            && resolveAuthoritativeNodeDefinition(node.getType()) != null;
    }

    private boolean isEditableWidget(FlowNodeWidget widget) {
        String nodeId = findNodeId(widget);
        return nodeId != null && isEditableNode(nodeId);
    }

    private boolean canMoveNode(String nodeId) {
        return canMutateNodeStructure(nodeId);
    }

    private boolean canMoveWidget(FlowNodeWidget widget) {
        String nodeId = findNodeId(widget);
        return nodeId != null && canMoveNode(nodeId);
    }

    private boolean canMutateNodeStructure(String nodeId) {
        if (!isActiveCoreStudioDocument()) {
            return isEditableNode(nodeId);
        }
        CoreGraphEditorSession session = coreInteractionSession();
        return nodeId != null && session != null && coreAuthoringNegotiated() && coreCapabilityAllowed(session)
            && coreNode(session, nodeId) != null && widgetCache.get(nodeId) != null;
    }

    private boolean canMutateWidgetStructure(FlowNodeWidget widget) {
        String nodeId = findNodeId(widget);
        return nodeId != null && canMutateNodeStructure(nodeId);
    }

    private boolean canDeleteNode(String nodeId) {
        if (!isActiveCoreStudioDocument()) {
            return isEditableNode(nodeId);
        }
        CoreGraphEditorSession session = coreInteractionSession();
        return canMutateNodeStructure(nodeId) && !isProtectedCoreNode(session, nodeId);
    }

    private boolean hasDeletableSelection() {
        return selectedNodeIds.stream().anyMatch(this::canDeleteNode);
    }

    private boolean hasEditableSelection() {
        return selectedNodeIds.stream().anyMatch(this::isEditableNode);
    }

    private void morphStudioResourceIntoNode(FlowNodeWidget widget) {
        int[] source = takeStudioResourceDragBounds();
        if (widget == null || source == null) {
            return;
        }
        double[] startScreen = unDistortMouse(source[0], source[1]);
        double[] endScreen = unDistortMouse(source[0] + source[2], source[1] + source[3]);
        double[] startWorld = screenToWorld(startScreen[0], startScreen[1]);
        double[] endWorld = screenToWorld(endScreen[0], endScreen[1]);
        int sourceWidth = Math.max(1, (int) Math.round(endWorld[0] - startWorld[0]));
        int sourceHeight = Math.max(1, (int) Math.round(endWorld[1] - startWorld[1]));
        int initialWidth = Math.min(sourceWidth, Math.max(32, Math.round(widget.getWidth() * 0.45f)));
        int initialHeight = Math.min(sourceHeight, Math.max(12, Math.round(widget.getHeight() * 0.35f)));
        double centerX = (startWorld[0] + endWorld[0]) / 2.0;
        double centerY = (startWorld[1] + endWorld[1]) / 2.0;
        widget.morphFromBounds(
            (int) Math.round(centerX - initialWidth / 2.0),
            (int) Math.round(centerY - initialHeight / 2.0),
            initialWidth,
            initialHeight
        );
    }

    private void completeStudioResourceDragToWorldBounds(Widget widget) {
        double[] start = worldToScreen(widget.getX(), widget.getY());
        double[] end = worldToScreen(widget.getX() + widget.getWidth(), widget.getY() + widget.getHeight());
        completeStudioResourceDragTo(
            (int) Math.round(start[0]),
            (int) Math.round(start[1]),
            Math.max(1, (int) Math.round(end[0] - start[0])),
            Math.max(1, (int) Math.round(end[1] - start[1])),
            true
        );
    }

    private boolean isGraphDropArea(double mouseX, double mouseY) {
        int left = studioContentBrowser != null ? studioContentBrowser.visibleLayoutWidth() : 0;
        int right = paletteSidePanel != null ? paletteSidePanel.layoutWidth(0) : 0;
        return mouseX > left && mouseX < width - right && mouseY > 30 && mouseY < height;
    }

    private boolean acceptsResource(FlowNodeWidget widget, String pin, ReSyncResourceDragPayload payload) {
        String source = widget.getInputOptionsSource(pin);
        if (("server:resync:" + payload.type()).equals(source)) {
            return true;
        }
        FlowTypeRef typeRef = widget.getPinTypeRef(pin, true);
        if (typeRef == null) {
            return false;
        }
        if (resourceValueType(payload.type()).equals(typeRef.getTypeId())) {
            return true;
        }
        return "resource_reference".equals(typeRef.getTypeId()) && !typeRef.getArguments().isEmpty()
            && payload.type().equals(typeRef.getArguments().getFirst().getTypeId());
    }

    private boolean isFlowConnection(FlowConnection connection) {
        FlowNodeWidget source = widgetCache.get(connection.getSourceNodeId());
        return source != null && source.getPinKind(connection.getSourcePin(), false) == NodeDefinition.PinType.FLOW;
    }

    private boolean hasFlowPath(NodeDefinition definition) {
        boolean input = definition.getInputs().stream().anyMatch(pin -> "flow".equals(pin.getName()) && pin.getType() == NodeDefinition.PinType.FLOW);
        boolean output = definition.getOutputs().stream().anyMatch(pin -> "flow".equals(pin.getName()) && pin.getType() == NodeDefinition.PinType.FLOW);
        return input && output;
    }

    private String resourceValueType(String resourceType) {
        return switch (resourceType) {
            case ReSyncResourceDragPayload.FLOW -> "flow_id";
            case ReSyncResourceDragPayload.FUNCTION -> "function";
            case ReSyncResourceDragPayload.COMMAND -> "command_id";
            case ReSyncResourceDragPayload.CUSTOM_CONTENT -> "custom_content_id";
            case ReSyncResourceDragPayload.GUI -> "gui_id";
            case ReSyncResourceDragPayload.SCOREBOARD -> "scoreboard_id";
            case ReSyncResourceDragPayload.TAB -> "tab_id";
            case ReSyncResourceDragPayload.CHAT -> "chat_id";
            case ReSyncResourceDragPayload.COMPONENT_BUILDER -> "component_builder_id";
            case ReSyncResourceDragPayload.MOTD_PROFILE -> "motd_profile_id";
            case ReSyncResourceDragPayload.MESSAGE_RULE -> "message_rule_id";
            case ReSyncResourceDragPayload.RECIPE_DEFINITION -> "recipe_id";
            case ReSyncResourceDragPayload.TEXT_TEMPLATE -> "text_template_id";
            case ReSyncResourceDragPayload.ADVANCEMENT_TREE -> "advancement_tree_id";
            case ReSyncResourceDragPayload.DIALOG -> "dialog_id";
            case ReSyncResourceDragPayload.TRADE_PROFILE -> "trade_profile_id";
            case ReSyncResourceDragPayload.NPC_DEFINITION -> "npc_id";
            case ReSyncResourceDragPayload.LOOT_TABLE -> "loot_table_id";
            case ReSyncResourceDragPayload.WORLDGEN -> "worldgen_id";
            case ReSyncResourceDragPayload.WORLD -> "world";
            case ReSyncResourceDragPayload.VARIABLE_DEFINITION -> "variable_reference";
            case ReSyncResourceDragPayload.TIMER_DEFINITION -> "timer_reference";
            case ReSyncResourceDragPayload.SCHEDULE_DEFINITION -> "schedule_reference";
            default -> "";
        };
    }

